def _positive_int(raw: object) -> int | None:
    """Return ``raw`` as an int if it is a string of digits, else ``None``."""
    if not isinstance(raw, str) or not raw.isdigit():
        return None
    try:
        return int(raw)
    except ValueError:
        return None


def handle_users_page(params: dict) -> tuple[int, dict]:
    page = _positive_int(params.get("page", "1"))
    page_size = _positive_int(params.get("page_size", "10"))
    if page is None or page_size is None:
        return 400, {"error": "invalid paging"}
    if page < 1 or not 1 <= page_size <= 50:
        return 400, {"error": "invalid paging"}

    total = users.count_users()
    offset = (page - 1) * page_size
    page_users = users.list_users(page_size, offset)
    return 200, {"users": page_users, "page": page, "page_size": page_size, "total": total}
